     3	declare(strict_types=1);
     4	
     5	namespace App\Analyzer\Graph;
     6	
     7	use App\Analyzer\Graph\Node\UnknownNode;
     8	use App\Analyzer\Graph\NodeId\UnknownNodeId;
     9	
    10	use function App\array_flatten;
    11	
    12	/**
    13	 * Represents a dependency graph of PHP code elements.
    14	 *
    15	 * The graph stores nodes (representing PHP code elements like classes, methods, etc.)
    16	 * and edges (representing relationships between those elements). It uses an adjacency
    17	 * list structure for efficient edge lookups and automatically creates bidirectional
    18	 * edges with inverted edge kinds.
    19	 */
    20	final class Graph
    21	{
    22	    /**
    23	     * @var array<string, Node> Map of node ID strings to Node objects
    24	     */
    25	    private array $nodes = [];
    26	
    27	    /**
    28	     * @var array<string, list<Edge>> Adjacency list mapping source node IDs to a list of edges
    29	     */
    30	    private array $adjacency = [];
    31	
    32	    /**
    33	     * @var array<string, true> Hash set for O(1) edge duplicate detection, keyed by "from\0kind\0to"
    34	     */
    35	    private array $edgeSet = [];
    36	
    37	    /**
    38	     * Adds a single node to the graph.
    39	     *
    40	     * If a node with the same ID already exists and is not Unknown, an exception is thrown.
    41	     * Unknown nodes can be replaced by concrete node types.
    42	     *
    43	     * @param Node $node The node to add to the graph
    44	     *
    45	     * @throws \InvalidArgumentException If a non-Unknown node with the same ID already exists
    46	     */
    47	    public function addNode(Node $node): void
    48	    {
    49	        $nodeKey = $node->id()->toString();
    50	        if (isset($this->nodes[$nodeKey]) && $this->nodes[$nodeKey]->kind() !== NodeKind::Unknown) {
    51	            throw new \InvalidArgumentException('Node already exists.');
    52	        }
    53	        $this->nodes[$nodeKey] = $node;
    54	        assert(
    55	            $this->nodes[$nodeKey] === $node,
    56	            'Contract violated: node not retrievable after addNode'
    57	        );
    58	        if (!isset($this->adjacency[$nodeKey])) {
    59	            $this->adjacency[$nodeKey] = [];
    60	        }
    61	    }
    62	
    63	    /**
    64	     * Adds multiple nodes to the graph.
    65	     *
    66	     * @param Node[] $nodes Array of nodes to add
    67	     */
    68	    public function addNodes(array $nodes): void
    69	    {
    70	        foreach ($nodes as $node) {
    71	            $this->addNode($node);
    72	        }
    73	    }
    74	
    75	    /**
    76	     * Adds a single edge to the graph.
    77	     *
    78	     * Automatically creates Unknown nodes for any referenced nodes that don't exist yet.
    79	     * Also creates a bidirectional edge in the opposite direction with an inverted edge kind.
    80	     *
    81	     * @param Edge $edge The edge to add to the graph
    82	     */
    83	    public function addEdge(Edge $edge): void
    84	    {
    85	        $fromKey = $edge->from()->toString();
    86	        $toKey = $edge->to()->toString();
    87	        $kind = $edge->kind();
    88	
    89	        if (!isset($this->nodes[$fromKey])) {
    90	            $unknownId = $edge->from() instanceof UnknownNodeId
    91	                ? $edge->from()
    92	                : new UnknownNodeId($fromKey);
    93	            $this->nodes[$fromKey] = new UnknownNode(
    94	                id: $unknownId,
    95	            );
    96	        }
    97	        if (!isset($this->nodes[$toKey])) {
    98	            $unknownId = $edge->to() instanceof UnknownNodeId
    99	                ? $edge->to()
   100	                : new UnknownNodeId($toKey);
   101	            $this->nodes[$toKey] = new UnknownNode(
   102	                id: $unknownId,
   103	            );
   104	        }
   105	
   106	        $edgeKey = $fromKey."\0".$kind->value."\0".$toKey;
   107	        if (isset($this->edgeSet[$edgeKey])) {
   108	            return;
   109	        }
   110	
   111	        $this->edgeSet[$edgeKey] = true;
   112	        $this->adjacency[$fromKey][] = $edge;
   113	
   114	        $inverse = $edge->invert();
   115	        $inverseKind = $inverse->kind();
   116	        $inverseToKey = $inverse->to()->toString();
   117	        $inverseKey = $toKey."\0".$inverseKind->value."\0".$inverseToKey;
   118	        if (!isset($this->edgeSet[$inverseKey])) {
   119	            $this->edgeSet[$inverseKey] = true;
   120	            $this->adjacency[$toKey][] = $inverse;
   121	        }
   122	        assert(
   123	            $this->edge($edge->from(), $edge->to(), $kind) !== null,
   124	            'Contract violated: forward edge must exist after addEdge'
   125	        );
   126	        assert(
   127	            $this->edge($edge->to(), $edge->from(), $inverse->kind()) !== null,
   128	            'Contract violated: inverse edge must exist after addEdge'
   129	        );
   130	    }
   131	
   132	    /**
   133	     * Adds multiple edges to the graph.
   134	     *
   135	     * @param Edge[] $edges Array of edges to add
   136	     */
   137	    public function addEdges(array $edges): void
   138	    {
   139	        foreach ($edges as $edge) {
   140	            $this->addEdge($edge);
   141	        }
   142	    }
   143	
   144	    /**
   145	     * Retrieves a node by its ID.
   146	     *
   147	     * @param NodeId<Node> $id The identifier of the node to retrieve
   148	     *
   149	     * @return null|Node The node if found, null otherwise
   150	     */
   151	    public function node(NodeId $id): ?Node
   152	    {
   153	        return $this->nodes[$id->toString()] ?? null;
   154	    }
   155	
   156	    /**
   157	     * Retrieves all nodes in the graph.
   158	     *
   159	     * @return Node[] Array of all nodes
   160	     */
   161	    public function nodes(): array
   162	    {
   163	        return array_values($this->nodes);
   164	    }
   165	
   166	    /**
   167	     * Retrieves an edge between two nodes, optionally filtered by kind.
   168	     *
   169	     * @param NodeId<Node>  $from Source node identifier
   170	     * @param NodeId<Node>  $to   Target node identifier
   171	     * @param null|EdgeKind $kind Optional edge kind filter; null returns the first match
   172	     *
   173	     * @return null|Edge The edge if found, null otherwise
   174	     */
   175	    public function edge(NodeId $from, NodeId $to, ?EdgeKind $kind = null): ?Edge
   176	    {
   177	        $edges = $this->adjacency[$from->toString()] ?? [];
   178	        foreach ($edges as $edge) {
   179	            if ($edge->to()->toString() === $to->toString()
   180	                && ($kind === null || $edge->kind() === $kind)
   181	            ) {
   182	                return $edge;
   183	            }
   184	        }
   185	
   186	        return null;
   187	    }
   188	
   189	    /**
   190	     * Retrieves all edges originating from a specific node.
   191	     *
   192	     * @param NodeId<Node> $from Source node identifier
   193	     *
   194	     * @return Edge[] Array of edges from the specified node
   195	     */
   196	    public function edges(NodeId $from): array
   197	    {
   198	        return $this->adjacency[$from->toString()] ?? [];
   199	    }
   200	
   201	    /**
   202	     * Merges this graph with another graph, returning a new merged graph.
   203	     *
   204	     * Creates a new graph containing all nodes and edges from both graphs.
   205	     * Existing Unknown nodes can be replaced by concrete types from the other graph.
   206	     *
   207	     * @param Graph $other The graph to merge with this one
   208	     *
   209	     * @return Graph A new graph containing nodes and edges from both graphs
   210	     */
   211	    public function merge(Graph $other): Graph
   212	    {
   213	        $merged = new Graph();
   214	        $nodes = array_merge(
   215	            $this->nodes(),
   216	            $other->nodes()
   217	        );
   218	        $merged->addNodes($nodes);
   219	
   220	        $edges = array_merge(
   221	            array_flatten($this->adjacency),
   222	            array_flatten($other->adjacency),
   223	        );
   224	        $merged->addEdges(
   225	            array_filter($edges, function (Edge $edge) {
   226	                return $edge->kind() !== EdgeKind::UsedBy && $edge->kind() !== EdgeKind::DeclaredIn;
   227	            })
   228	        );
   229	
   230	        return $merged;
   231	    }
   232	}
