 45	        parent::__construct();
 46	    }
 47	
 48	    /**
 49	     * Configures the command options and arguments.
 50	     */
 51	    protected function configure(): void
 52	    {
 53	        $this->addOption(
 54	            'config',
 55	            null,
 56	            InputOption::VALUE_REQUIRED,
