 68	            InputOption::VALUE_REQUIRED,
 69	            'Limit depth of the dependency graph',
 70	        )->addOption(
 71	            'reverse',
 72	            'R',
 73	            InputOption::VALUE_NONE,
 74	            'Shortcut for --direction used-by',
 75	        )->addOption(
 76	            'include',
 77	            'I',
 78	            InputOption::VALUE_IS_ARRAY | InputOption::VALUE_REQUIRED,
 79	            'Include patterns',
 80	            [],
 81	        )->addOption(
 82	            'exclude',
 83	            'E',
 84	            InputOption::VALUE_IS_ARRAY | InputOption::VALUE_REQUIRED,
 85	            'Exclude patterns',
 86	            [],
 87	        )->addOption(
 88	            'type',
 89	            null,
 90	            InputOption::VALUE_REQUIRED,
 91	            'Analyzer type (phpstan|debug)',
 92	        )->addOption(
 93	            'debug-depth',
 94	            null,
 95	            InputOption::VALUE_REQUIRED,
 96	            'Debug analyzer depth',
 97	        )->addOption(
 98	            'debug-seed',
 99	            null,
100	            InputOption::VALUE_REQUIRED,
101	            'Debug analyzer seed',
102	        )->addOption(
103	            'memory-limit',
104	            null,
105	            InputOption::VALUE_REQUIRED,
106	            'Memory limit (e.g. 1G, 256M)',
107	        );
108	        $this->addArgument(
109	            'target',
110	            InputArgument::REQUIRED,
111	            'Namespace\ClassName, Namespace\ClassName::methodName or Namespace\functionName',
112	        );
113	        $this->addArgument(
114	            'path',
115	            InputArgument::OPTIONAL,
116	            'Base directory to analyze (default: current working dir)',
117	        );
118	    }
119	
120	    /**
121	     * Executes the inspection command.
122	     *
123	     * @param InputInterface  $input  The input interface
124	     * @param OutputInterface $output The output interface
125	     *
126	     * @return int The command exit code
127	     */
128	    protected function execute(InputInterface $input, OutputInterface $output): int
129	    {
130	        $memoryLimit = $input->getOption('memory-limit');
131	        if (is_string($memoryLimit)) {
132	            ini_set('memory_limit', $memoryLimit);
133	        }
134	
135	        $target = $input->getArgument('target');
136	        if (!is_string($target)) {
137	            $output->writeln('<error>Target argument must be a string</error>');
138	
139	            return Command::INVALID;
140	        }
141	
142	        $path = $input->getOption('config');
143	        if (!is_string($path)) {
144	            $output->writeln('<error>Path argument must be a string</error>');
145	
146	            return Command::INVALID;
147	        }
148	
149	        $loader = new ConfigLoader([
150	            new DefaultConfigReader(),
151	            new YamlConfigLoader($path),
152	            new EnvConfigReader(),
153	            new InputConfigReader($input),
154	        ]);
155	        $config = $loader->load();
156	
157	        $result = $this->action->execute(new InspectActionInput(
158	            config: $config,
159	            target: $target,
160	        ));
161	
162	        $symbol = null;
163	        foreach ($result->graph->nodes() as $node) {
164	            if ($node->id()->toString() === $target) {
165	                $symbol = $node;
166	
167	                break;
168	            }
169	        }
170	        if ($symbol === null) {
171	            $output->writeln(sprintf('<error>Target "%s" not found in the dependency graph</error>', $target));
172	
173	            return Command::FAILURE;
174	        }
175	
176	        $reporter = new TreeReporter(
177	            options: new TreeReporterOptions(
178	                level: $config->level,
179	            ),
180	            traversal: $config->direction === 'uses'
181	                ? new DependencyTraversal()
182	                : new DependsTraversal(),
183	        );
184	        $reporter->report($result->graph, $symbol->id(), $output);
185	
186	        return Command::SUCCESS;
187	    }
188	}

