 9	use App\Analyzer\Graph\NodeId;
10	
11	/**
12	 * Unique identifier for a class node in the dependency graph.
13	 *
14	 * Represents a fully qualified class identifier consisting of a namespace
15	 * and class name. This ID uniquely identifies a PHP class within the analyzed codebase.
16	 *
17	 * @implements NodeId<ClassNode>
18	 *
19	 * @property string $fullQualifiedName Alias for fullQualifiedName()
20	 */
21	final class ClassNodeId implements NodeId
22	{
23	    use IdentifierAssert;
24	
25	    /**
26	     * @param string $namespace The namespace of the class (must be a valid PHP namespace)
27	     * @param string $className The class name (must be a valid PHP identifier)
28	     */
29	    private readonly string $stringValue;
30	
31	    public function __construct(
32	        public readonly string $namespace,
33	        public readonly string $className,
34	    ) {
35	        if ($namespace !== '') {
36	            self::assertNamespace($namespace);
37	        }
38	        self::assertIdentifier($className);
39	        $this->stringValue = $namespace === '' ? $className : $namespace.'\\'.$className;
40	    }
41	
42	    public function __toString(): string
43	    {
44	        return $this->toString();
45	    }
46	
47	    public function __get(string $name): mixed
48	    {
49	        return match ($name) {
50	            'fullQualifiedName' => $this->fullQualifiedName(),
51	            default => throw new \LogicException("Undefined property: {$name}"),
52	        };
53	    }
54	
55	    /**
56	     * Returns the fully qualified class name.
57	     *
