 18	/**
 19	 * Represents a reverse usage relationship (e.g., function called by method).
 20	 */
 21	final class UsedByEdge implements Edge
 22	{
 23	    use EdgeTrait;
 24	
 25	    /**
 26	     * @param Node     $from Source node
 27	     * @param Node     $to   Target node
 28	     * @param FileMeta $meta Metadata about where this relationship is defined in source code
 29	     */
 30	    public function __construct(
 31	        Node $from,
 32	        Node $to,
 33	        FileMeta $meta,
 34	    ) {
 35	        $this->fromNode = $from;
 36	        $this->toNode = $to;
 37	        $this->meta = $meta;
 38	    }
 39	
 40	    public function kind(): EdgeKind
 41	    {
 42	        return EdgeKind::UsedBy;
 43	    }
 44	
 45	    public function invert(): Edge
 46	    {
 47	        $from = $this->fromNode;
 48	        $to = $this->toNode;
 49	
 50	        if ($from instanceof FunctionNode) {
 51	            assert($to instanceof MethodNode || $to instanceof FunctionNode);
 52	
 53	            return new FunctionCallEdge(from: $to, to: $from, meta: $this->meta);
 54	        }
 55	
 56	        if ($from instanceof ConstantNode) {
 57	            assert($to instanceof MethodNode || $to instanceof FunctionNode);
 58	
 59	            return new ConstFetchEdge(from: $to, to: $from, meta: $this->meta);
 60	        }
 61	
 62	        if ($from instanceof ClassNode) {
 63	            assert($to instanceof MethodNode || $to instanceof FunctionNode);
 64	
 65	            return new InstantiationEdge(from: $to, to: $from, meta: $this->meta);
 66	        }
 67	
 68	        if ($from instanceof PropertyNode) {
 69	            assert($to instanceof MethodNode || $to instanceof FunctionNode);
 70	
 71	            return new PropertyAccessEdge(from: $to, to: $from, meta: $this->meta);
 72	        }
 73	
 74	        if ($from instanceof MethodNode) {
 75	            assert($to instanceof MethodNode || $to instanceof FunctionNode);
 76	
 77	            return new MethodCallEdge(from: $to, to: $from, meta: $this->meta);
 78	        }
 79	
 80	        throw new \LogicException('Cannot invert UsedByEdge: unknown node combination.');
 81	    }
 82	}
