 26	final class DeclaredInEdge implements Edge
 27	{
 28	    use EdgeTrait;
 29	
 30	    /**
 31	     * @param Node     $from Source node
 32	     * @param Node     $to   Target node
 33	     * @param FileMeta $meta Metadata about where this relationship is defined in source code
 34	     */
 35	    public function __construct(
 36	        Node $from,
 37	        Node $to,
 38	        FileMeta $meta,
 39	    ) {
 40	        $this->fromNode = $from;
 41	        $this->toNode = $to;
 42	        $this->meta = $meta;
 43	    }
 44	
 45	    public function kind(): EdgeKind
 46	    {
 47	        return EdgeKind::DeclaredIn;
 48	    }
 49	
 50	    public function invert(): Edge
 51	    {
 52	        $from = $this->fromNode;
 53	        $to = $this->toNode;
 54	
 55	        if ($from instanceof MethodNode) {
 56	            assert($to instanceof ClassNode || $to instanceof GraphInterfaceNode || $to instanceof TraitNode || $to instanceof EnumNode);
 57	
 58	            return new DeclarationMethodEdge(from: $to, to: $from, meta: $this->meta);
 59	        }
 60	
 61	        if ($from instanceof PropertyNode) {
 62	            assert($to instanceof ClassNode || $to instanceof TraitNode);
 63	
 64	            return new DeclarationPropertyEdge(from: $to, to: $from, meta: $this->meta);
 65	        }
 66	
 67	        if ($from instanceof ConstantNode) {
 68	            assert($to instanceof ClassNode || $to instanceof GraphInterfaceNode);
 69	
 70	            return new DeclarationConstantEdge(from: $to, to: $from, meta: $this->meta);
 71	        }
 72	
 73	        if ($from instanceof EnumCaseNode) {
 74	            assert($to instanceof EnumNode);
 75	
 76	            return new DeclarationEnumCaseEdge(from: $to, to: $from, meta: $this->meta);
 77	        }
 78	
 79	        if ($to instanceof ClassNode) {
 80	            if ($from instanceof ClassNode) {
 81	                return new DeclarationExtendsEdge(from: $to, to: $from, meta: $this->meta);
 82	            }
 83	            if ($from instanceof GraphInterfaceNode) {
 84	                return new DeclarationImplementsEdge(from: $to, to: $from, meta: $this->meta);
 85	            }
 86	            if ($from instanceof TraitNode) {
 87	                return new DeclarationTraitUseEdge(from: $to, to: $from, meta: $this->meta);
 88	            }
 89	        }
 90	
 91	        if ($to instanceof PropertyNode) {
 92	            assert($from instanceof ClassNode || $from instanceof GraphInterfaceNode || $from instanceof EnumNode || $from instanceof TraitNode || $from instanceof BuiltinNode);
 93	
 94	            return new DeclarationTypePropertyEdge(from: $to, to: $from, meta: $this->meta);
