  5	namespace App\Reporter\TreeReporter;
  6	
  7	use App\Analyzer\Graph\Graph;
  8	use App\Analyzer\Graph\Node;
  9	use App\Analyzer\Graph\NodeId;
 10	use App\Analyzer\Graph\NodeKind;
 11	use App\Reporter\Reporter;
 12	use App\Reporter\Traversal;
 13	use App\Reporter\Traversal\DependencyTraversal;
 14	use Symfony\Component\Console\Output\OutputInterface;
 15	
 16	/**
 17	 * Reports analysis results as a text-based tree structure.
 18	 *
 19	 * This reporter visualizes the dependency graph as a hierarchical tree, similar to the
 20	 * Unix `tree` command. It uses a traversal strategy to visit nodes and a line renderer
 21	 * to format the output. It supports depth limiting and handles cyclic dependencies.
 22	 */
 23	final class TreeReporter implements Reporter
 24	{
 25	    public function __construct(
 26	        private readonly TreeReporterOptions $options,
 27	        private readonly Traversal $traversal = new DependencyTraversal(),
 28	        private readonly LineRenderer $lineRenderer = new LineRenderer(),
 29	    ) {}
 30	
 31	    /**
 32	     * {@inheritdoc}
 33	     */
 34	    public function report(Graph $graph, NodeId $symbol, OutputInterface $output): void
 35	    {
 36	        $continuationFlags = [];
 37	        $parentStack = [];
 38	        $pathStack = [];
 39	        $expanded = [];
 40	
 41	        $this->traversal->traverse(
 42	            $graph,
 43	            $symbol,
 44	            function (
 45	                Node $node,
 46	                int $depth
 47	            ) use (
 48	                $graph,
 49	                $output,
 50	                &$continuationFlags,
 51	                &$parentStack,
 52	                &$pathStack,
 53	                &$expanded
 54	            ) {
 55	                if ($this->options->level !== null && $depth > $this->options->level) {
 56	                    return false;
 57	                }
 58	
 59	                while (count($pathStack) > $depth) {
 60	                    array_pop($pathStack);
 61	                }
 62	
 63	                $nodeKey = $node->id()->toString();
 64	
 65	                $isRecursive = in_array($nodeKey, $pathStack, true);
 66	                $isDuplicate = !$isRecursive && isset($expanded[$nodeKey]);
 67	
 68	                $isLastChild = true;
 69	                if ($depth > 0 && isset($parentStack[$depth - 1])) {
 70	                    $parentNode = $parentStack[$depth - 1];
 71	                    $siblings = [];
 72	                    $edges = $graph->edges($parentNode->id());
 73	                    foreach ($edges as $edge) {
 74	                        if ($this->traversal->isTraversableEdge($edge->kind())) {
 75	                            $siblings[] = $edge->to()->toString();
 76	                        }
 77	                    }
 78	
 79	                    $siblings = array_unique($siblings);
 80	                    if ($siblings !== []) {
 81	                        $lastSiblingId = end($siblings);
 82	                        $isLastChild = ($nodeKey === $lastSiblingId);
 83	                    }
 84	                }
 85	
 86	                $line = $this->lineRenderer->render($node, $depth, $continuationFlags, $isLastChild, $isRecursive, $isDuplicate);
 87	                $output->writeln($line);
 88	
 89	                $continuationFlags[$depth] = !$isLastChild;
 90	
 91	                $parentStack[$depth] = $node;
 92	
 93	                if (!$isRecursive) {
 94	                    $pathStack[] = $nodeKey;
 95	                }
 96	
 97	                if (
 98	                    $isRecursive
 99	                    || $isDuplicate
100	                    || $node->kind() === NodeKind::Builtin
101	                    || $node->kind() === NodeKind::Unknown
102	                ) {
103	                    return false;
104	                }
105	
106	                $expanded[$nodeKey] = true;
107	
108	                return true;
109	            }
110	        );
111	    }
112	}
