 10	/**
 11	 * Renders a single line of the dependency tree.
 12	 *
 13	 * This class is responsible for formatting the tree structure characters (│, ├──, └──)
 14	 * and the node information (ID, recursion status, builtin status) for a single node
 15	 * in the dependency tree output.
 16	 */
 17	final class LineRenderer
 18	{
 19	    /**
 20	     * @param bool[] $continuationFlags
 21	     *
 22	     * @return string
 23	     *
 24	     * Example outputs:
 25	     * - Root node (depth=0): MyClass
 26	     * - First level, not last child: ├── MyClass::method1
 27	     * - First level, last child: └── MyClass::method2
 28	     * - Second level with continuation, not last child: │   ├── Dependency1
 29	     * - Second level with continuation, last child: │   └── Dependency2
 30	     * - Second level without continuation, not last child:     ├── OtherDep1
 31	     * - Second level without continuation, last child:     └── OtherDep2
 32	     * - Third level with multiple continuations: │   │   ├── DeepDep
 33	     * - Third level with partial continuations: │       └── DeepDep
 34	     * - Deep nesting (depth >= 3): │   │   │   └── VeryDeepDep
 35	     * - Builtin function reference: ├── array_map (builtin)
 36	     * - Recursive reference detected: │   └── MyClass::method1 (recursive)
 37	     * - Unresolved reference: ├── UnknownClass (unresolved)
 38	     * - Builtin at deep level: │   │   └── strlen (builtin)
 39	     * - Mixed recursive and continuation: │   ├── Helper::process (recursive)
 40	     * - Duplicate (already expanded elsewhere): │   └── SharedDep (*)
 41	     */
 42	    public function render(
 43	        Node $node,
 44	        int $depth,
 45	        array $continuationFlags,
 46	        bool $isLastChild,
 47	        bool $isRecursive,
 48	        bool $isDuplicate = false,
 49	    ): string {
 50	        if ($depth === 0) {
 51	            return $node->id()->toString();
 52	        }
 53	
 54	        $line = '';
 55	
 56	        for ($i = 1; $i < $depth; ++$i) {
 57	            $line .= ($continuationFlags[$i] ?? false) ? '│   ' : '    ';
 58	        }
 59	
 60	        $line .= $isLastChild ? '└── ' : '├── ';
 61	
 62	        $line .= $node->id()->toString();
 63	
 64	        if ($isRecursive) {
 65	            $line .= ' (recursive)';
 66	        } elseif ($isDuplicate) {
 67	            $line .= ' (*)';
 68	        } elseif ($node->kind() === NodeKind::Builtin) {
 69	            $line .= ' (builtin)';
 70	        } elseif ($node->kind() === NodeKind::Unknown) {
 71	            $line .= ' (unresolved)';
 72	        }
 73	
 74	        return $line;
 75	    }
 76	}
