 25	    case Enum = 'enum';
 26	
 27	    /** Represents a global function */
 28	    case Function = 'function';
 29	
 30	    /** Represents a PHP interface */
 31	    case Interface = 'interface';
 32	
 33	    /** Represents a class method */
 34	    case Method = 'method';
 35	
 36	    /** Represents a class property */
 37	    case Property = 'property';
 38	
 39	    /** Represents a PHP trait */
 40	    case Trait = 'trait';
 41	
 42	    /** Represents a builtin PHP type (e.g., string, int, array) */
 43	    case Builtin = 'builtin';
 44	
 45	    /** Represents an unknown or unresolved type */
 46	    case Unknown = 'unknown';
