  5	namespace App\Analyzer\PhpStanAnalyzer;
  6	
  7	use App\Analyzer\Analyzer;
  8	use App\Analyzer\Graph\Edge;
  9	use App\Analyzer\Graph\Graph;
 10	use App\Analyzer\Graph\Node;
 11	use App\Analyzer\PhpStanAnalyzer\Collector\DependencyCollector;
 12	use App\Analyzer\PhpStanAnalyzer\Collector\InClassMethodCollector;
 13	use PHPStan\Analyser\Analyser as PhpStanAnalyser;
 14	
 15	final class PhpStanAnalyzer implements Analyzer
 16	{
 17	    /**
 18	     * @param string[] $includes File path patterns to include in analysis
 19	     * @param string[] $excludes File path patterns to exclude from analysis
 20	     */
 21	    public function __construct(
 22	        private readonly ContainerFactory $containerFactory,
 23	        private readonly PhpFileCollector $fileCollector,
 24	        private readonly array $includes = [],
 25	        private readonly array $excludes = [],
 26	    ) {}
 27	
 28	    public function analyze(string $path): Graph
 29	    {
 30	        $realPath = realpath($path);
 31	        $absolutePath = $realPath !== false ? $realPath : $path;
 32	        $files = $this->fileCollector->collect([$absolutePath], $this->includes, $this->excludes);
 33	
 34	        if ($files === []) {
 35	            return new Graph();
 36	        }
 37	
 38	        $container = $this->containerFactory->create($files);
 39	        // @phpstan-ignore phpstanApi.classConstant
 40	        $analyser = $container->getByType(PhpStanAnalyser::class);
 41	
 42	        // Run analysis
 43	        // @phpstan-ignore phpstanApi.method
 44	        $result = $analyser->analyse($files, null, null, false, $files);
 45	
 46	        // Retrieve collected data
 47	        // @phpstan-ignore phpstanApi.method
 48	        $collectedData = $result->getCollectedData();
 49	
 50	        // Filter for our collector
 51	        /** @var array<Edge|Node> $items */
 52	        $items = [];
 53	        foreach ($collectedData as $file => $data) {
 54	            $this->collectItems($data, DependencyCollector::class, $items);
 55	            $this->collectItems($data, InClassMethodCollector::class, $items);
 56	        }
 57	
 58	        $graph = new Graph();
 59	
 60	        // Pass 1: Add all Nodes
 61	        foreach ($items as $item) {
 62	            if ($item instanceof Node) {
 63	                try {
 64	                    $graph->addNode($item);
 65	                } catch (\InvalidArgumentException) {
 66	                    // Ignore duplicates
 67	                }
 68	            }
 69	        }
 70	
 71	        // Pass 2: Add all Edges
 72	        foreach ($items as $item) {
 73	            if ($item instanceof Edge) {
 74	                $graph->addEdge($item);
 75	            }
 76	        }
 77	
 78	        return $graph;
 79	    }
 80	
 81	    /**
 82	     * @param array<string, mixed> $data
 83	     * @param class-string         $collectorClass
 84	     * @param array<Edge|Node>     $items
 85	     */
 86	    private function collectItems(array $data, string $collectorClass, array &$items): void
 87	    {
 88	        if (!isset($data[$collectorClass]) || !is_array($data[$collectorClass])) {
 89	            return;
 90	        }
 91	
 92	        foreach ($data[$collectorClass] as $nodeItems) {
 93	            if (is_array($nodeItems)) {
 94	                /** @var array<Edge|Node> $nodeItems */
 95	                foreach ($nodeItems as $item) {
 96	                    $items[] = $item;
 97	                }
 98	            }
 99	        }
100	    }
101	}
