10	 * This reader extracts configuration values from environment variables with a
11	 * specific prefix (default: 'PEQ_'). Variable names are converted from SCREAMING_SNAKE_CASE
12	 * to camelCase to match the Config class property names. This allows configuration
13	 * to be provided via environment variables in CI/CD pipelines or containerized environments.
14	 *
15	 * Array values (includes, excludes) use comma-separated format: PEQ_EXCLUDES=vendor,tests
16	 * Integer values (level) are automatically converted from strings.
17	 */
18	final class EnvConfigReader implements ConfigReader
19	{
20	    private const ARRAY_KEYS = ['includes', 'excludes'];
21	
22	    private const INT_KEYS = ['level'];
23	
24	    /**
25	     * @param string $prefix The prefix for environment variables to read (e.g., 'PEQ_')
26	     */
27	    public function __construct(
28	        private readonly string $prefix = 'PEQ_'
29	    ) {}
30	
31	    /**
32	     * {@inheritdoc}
33	     */
34	    public function read(): array
35	    {
36	        $config = [];
37	        foreach (getenv() as $name => $value) {
38	            if (!str_starts_with($name, $this->prefix)) {
39	                continue;
40	            }
41	
42	            $name = substr($name, strlen($this->prefix));
43	            $name = strtolower($name);
44	
45	            if (str_starts_with($name, 'debug_')) {
46	                $subKey = substr($name, 6);
47	                if (!isset($config['debug']) || !is_array($config['debug'])) {
48	                    $config['debug'] = [];
49	                }
50	                $config['debug'][$subKey] = $this->castValue($subKey, $value);
51	
52	                continue;
53	            }
54	
55	            $name = preg_replace_callback('/_([a-z])/', function ($matches) {
56	                return strtoupper($matches[1]);
57	            }, $name);
58	
59	            if (!is_string($name)) {
60	                continue;
61	            }
62	
63	            $config[$name] = $this->castValue($name, $value);
64	        }
