70	     * @return int|list<string>|string
71	     */
72	    private function castValue(string $key, string $value): array|int|string
73	    {
74	        if (in_array($key, self::ARRAY_KEYS, true)) {
75	            return $value !== '' ? array_map('trim', explode(',', $value)) : [];
