24	    ) {}
25	
26	    /**
27	     * {@inheritdoc}
28	     */
29	    public function read(): array
30	    {
31	        $config = [];
32	
33	        $path = $this->input->getArgument('path');
34	        if (is_string($path)) {
35	            $config['basePath'] = $path;
36	        }
