 7	use Symfony\Component\Yaml\Exception\ParseException;
 8	use Symfony\Component\Yaml\Yaml;
 9	
10	/**
11	 * Reads configuration from a YAML file.
12	 *
13	 * This reader loads configuration data from a YAML file (typically .peq.yaml)
14	 * using Symfony's YAML parser. If the file doesn't exist, it returns an empty
15	 * array, allowing the application to continue with other configuration sources.
16	 * YAML parsing errors are wrapped in ConfigException for consistent error handling.
17	 */
18	final class YamlConfigLoader implements ConfigReader
19	{
20	    /**
21	     * @param string $path Path to the YAML configuration file
22	     */
23	    public function __construct(
24	        private readonly string $path,
25	    ) {}
26	
27	    /**
28	     * {@inheritdoc}
29	     */
30	    public function read(): array
31	    {
32	        if (!file_exists($this->path)) {
33	            return [];
34	        }
35	
36	        $contents = @file_get_contents($this->path);
37	        if ($contents === false) {
38	            throw new ConfigException(sprintf('Failed to read configuration file: %s', $this->path));
39	        }
40	
41	        try {
42	            $config = Yaml::parse($contents);
43	        } catch (ParseException $e) {
44	            throw new ConfigException(
45	                sprintf('Failed to parse YAML configuration file "%s": %s', $this->path, $e->getMessage()),
46	                $e->getCode(),
47	                $e
48	            );
49	        }
50	
51	        if (!is_array($config)) {
52	            throw new ConfigException(
53	                sprintf(
54	                    'Invalid configuration format in "%s": Expected array, got %s',
55	                    $this->path,
56	                    get_debug_type($config)
57	                )
58	            );
59	        }
60	
61	        /** @var array<string, mixed> $config */
62	        return $config;
63	    }
