 32	 * @property GraphGenerator $generator
 33	 */
 34	final class AtomicProvider extends Base
 35	{
 36	    /**
 37	     * Generates a random NodeKind.
 38	     *
 39	     * @return NodeKind One of the available node kind enumeration values
 40	     */
 41	    public function nodeKind(): NodeKind
 42	    {
 43	        $kinds = NodeKind::cases();
 44	
 45	        return $kinds[$this->generator->numberBetween(0, count($kinds) - 1)];
 46	    }
 47	
 48	    /**
 49	     * Generates a random EdgeKind.
 50	     *
 51	     * Excludes UsedBy and DeclaredIn as these are reverse edge kinds that should
 52	     * only be created automatically by Graph::addEdge(), not generated directly.
 53	     *
 54	     * @return EdgeKind One of the available edge kind enumeration values
 55	     */
 56	    public function edgeKind(): EdgeKind
 57	    {
 58	        $kinds = array_values(array_filter(
 59	            EdgeKind::cases(),
 60	            fn ($kind) => $kind !== EdgeKind::UsedBy && $kind !== EdgeKind::DeclaredIn
 61	        ));
 62	
 63	        return $kinds[$this->generator->numberBetween(0, count($kinds) - 1)];
 64	    }
