 70	     *
 71	     * @return NodeId<Node> A node identifier appropriate for the specified kind
 72	     */
 73	    public function nodeId(?NodeKind $kind = null): NodeId
 74	    {
 75	        $kind ??= $this->nodeKind();
 76	
 77	        return match ($kind) {
 78	            NodeKind::Klass => $this->classNodeId(),
 79	            NodeKind::Interface => $this->interfaceNodeId(),
 80	            NodeKind::Trait => $this->traitNodeId(),
 81	            NodeKind::Enum => $this->enumNodeId(),
