246	    /**
247	     * Generates a trait graph with its methods and properties.
248	     *
249	     * @param null|TraitNodeId $symbol Optional trait NodeId to use as root
250	     * @param int              $depth  Maximum recursion depth (default: 20)
251	     *
252	     * @return Graph The trait graph
253	     */
254	    private function traitGraph(?TraitNodeId $symbol = null, int $depth = 5): Graph
255	    {
256	        $graph = new Graph();
257	
258	        $traitId = $symbol ?? $this->generator->traitNodeId();
259	        $trait = new TraitNode(
260	            id: $traitId,
261	            resolved: $this->generator->boolean(),
262	            meta: $this->generator->fileMeta(),
263	        );
264	        $graph->addNode($trait);
265	
266	        if ($depth === 0) {
267	            return $graph;
268	        }
269	
270	        $methodIds = $this->generator->array(fn () => $this->generator->methodNodeId(), 0, 5);
271	        foreach ($methodIds as $methodId) {
272	            $methodGraph = $this->methodGraph($methodId, $depth - 1);
273	            $graph = $graph->merge($methodGraph);
274	            $method = $graph->node($methodId);
275	            assert($method instanceof MethodNode);
276	            $graph->addEdge(new DeclarationMethodEdge($trait, $method, $this->generator->fileMeta()));
277	        }
278	
279	        $propertyIds = $this->generator->array(fn () => $this->generator->propertyNodeId(), 0, 5);
280	        foreach ($propertyIds as $propertyId) {
281	            $propertyGraph = $this->propertyGraph($propertyId, $depth - 1);
282	            $graph = $graph->merge($propertyGraph);
283	            $property = $graph->node($propertyId);
284	            assert($property instanceof PropertyNode);
285	            $graph->addEdge(new DeclarationPropertyEdge($trait, $property, $this->generator->fileMeta()));
286	        }
287	
288	        return $graph;
289	    }
