291	    /**
292	     * Generates a method graph with parameters, return type, and method body dependencies.
293	     *
294	     * @param null|MethodNodeId $symbol Optional method NodeId to use as root
295	     * @param int               $depth  Maximum recursion depth (default: 20)
296	     *
297	     * @return Graph The method graph
298	     */
299	    private function methodGraph(?MethodNodeId $symbol = null, int $depth = 5): Graph
300	    {
301	        $graph = new Graph();
302	
303	        $methodId = $symbol ?? $this->generator->methodNodeId();
304	        $method = new MethodNode(
305	            id: $methodId,
306	            resolved: $this->generator->boolean(),
307	            meta: $this->generator->fileMeta(),
308	        );
309	        $graph->addNode($method);
310	
311	        if ($depth === 0) {
312	            return $graph;
313	        }
314	
315	        $returnTypeId = $this->generator->typeNodeId();
316	        $returnTypeGraph = $this->typeGraph($returnTypeId, $depth - 1);
317	        $graph = $graph->merge($returnTypeGraph);
318	
319	        /** @var BuiltinNode|ClassNode|EnumNode|GraphInterfaceNode $returnType */
320	        $returnType = $graph->node($returnTypeId);
321	        $edge = new DeclarationTypeReturnEdge(
322	            from: $method,
323	            to: $returnType,
324	            meta: $this->generator->fileMeta()
325	        );
326	        $graph->addEdge($edge);
327	
328	        $paramTypeIds = $this->generator->array(fn () => $this->generator->typeNodeId(), 0, 5);
329	
330	        foreach ($paramTypeIds as $paramTypeId) {
331	            $paramTypeGraph = $this->typeGraph($paramTypeId, $depth - 1);
332	
333	            $graph = $graph->merge($paramTypeGraph);
334	            $paramType = $graph->node($paramTypeId);
335	            assert(
336	                $paramType instanceof ClassNode
337	                || $paramType instanceof GraphInterfaceNode
338	                || $paramType instanceof EnumNode
339	                || $paramType instanceof TraitNode
340	                || $paramType instanceof BuiltinNode
341	            );
342	            $graph->addEdge(new DeclarationTypeParameterEdge(
343	                $method,
344	                $paramType,
345	                $this->generator->fileMeta()
346	            ));
347	        }
348	
349	        /** @var null|MethodNodeId $calledMethodId */
350	        // @phpstan-ignore-next-line
351	        $calledMethodId = $this->generator->optional()->methodNodeId();
352	        if ($calledMethodId !== null) {
353	            $calledGraph = $this->methodGraph($calledMethodId, $depth - 1);
354	            $graph = $graph->merge($calledGraph);
355	            $calledMethod = $graph->node($calledMethodId);
356	            assert($calledMethod instanceof MethodNode);
357	            $graph->addEdge(new MethodCallEdge($method, $calledMethod, $this->generator->fileMeta()));
358	        }
359	
360	        /** @var null|MethodNodeId $staticMethodId */
361	        // @phpstan-ignore-next-line
362	        $staticMethodId = $this->generator->optional()->methodNodeId();
363	        if ($staticMethodId !== null) {
364	            $staticGraph = $this->methodGraph($staticMethodId, $depth - 1);
365	            $graph = $graph->merge($staticGraph);
366	            $staticMethod = $graph->node($staticMethodId);
367	            assert($staticMethod instanceof MethodNode);
368	            $graph->addEdge(new StaticCallEdge($method, $staticMethod, $this->generator->fileMeta()));
369	        }
370	
371	        /** @var null|FunctionNodeId $funcId */
372	        // @phpstan-ignore-next-line
373	        $funcId = $this->generator->optional()->functionNodeId();
374	        if ($funcId !== null) {
375	            $funcGraph = $this->functionGraph($funcId, $depth - 1);
376	            $graph = $graph->merge($funcGraph);
377	            $func = $graph->node($funcId);
378	            assert($func instanceof FunctionNode);
379	            $graph->addEdge(new FunctionCallEdge($method, $func, $this->generator->fileMeta()));
380	        }
381	
382	        /** @var null|PropertyNodeId $propId */
383	        // @phpstan-ignore-next-line
384	        $propId = $this->generator->optional()->propertyNodeId();
385	        if ($propId !== null) {
386	            $propGraph = $this->propertyGraph($propId, $depth - 1);
387	            $graph = $graph->merge($propGraph);
388	            $prop = $graph->node($propId);
389	            assert($prop instanceof PropertyNode);
390	            $graph->addEdge(new PropertyAccessEdge($method, $prop, $this->generator->fileMeta()));
391	        }
392	
393	        /** @var null|PropertyNodeId $staticPropId */
394	        // @phpstan-ignore-next-line
395	        $staticPropId = $this->generator->optional()->propertyNodeId();
396	        if ($staticPropId !== null) {
397	            $staticPropGraph = $this->propertyGraph($staticPropId, $depth - 1);
398	            $graph = $graph->merge($staticPropGraph);
399	            $staticProp = $graph->node($staticPropId);
400	            assert($staticProp instanceof PropertyNode);
401	            $graph->addEdge(new StaticPropertyAccessEdge($method, $staticProp, $this->generator->fileMeta()));
402	        }
403	
404	        /** @var null|ConstantNodeId $constId */
405	        // @phpstan-ignore-next-line
406	        $constId = $this->generator->optional()->constantNodeId();
407	        if ($constId !== null) {
408	            $constGraph = $this->constantGraph($constId);
409	            $graph = $graph->merge($constGraph);
410	            $const = $graph->node($constId);
411	            assert($const instanceof ConstantNode);
412	            $graph->addEdge(new ConstFetchEdge($method, $const, $this->generator->fileMeta()));
413	        }
414	
415	        /** @var null|ClassNodeId $instantiatedId */
416	        // @phpstan-ignore-next-line
417	        $instantiatedId = $this->generator->optional()->classNodeId();
418	        if ($instantiatedId !== null) {
419	            $instantiatedGraph = $this->classGraph($instantiatedId, $depth - 1);
420	            $graph = $graph->merge($instantiatedGraph);
421	            $instantiated = $graph->node($instantiatedId);
422	            assert($instantiated instanceof ClassNode);
423	            $graph->addEdge(new InstantiationEdge($method, $instantiated, $this->generator->fileMeta()));
424	        }
425	
426	        return $graph;
427	    }
428	
429	    /**
430	     * Generates a function graph with parameters, return type, and function body dependencies.
431	     *
432	     * @param null|FunctionNodeId $symbol Optional function NodeId to use as root
433	     * @param int                 $depth  Maximum recursion depth (default: 20)
434	     *
435	     * @return Graph The function graph
436	     */
437	    private function functionGraph(?FunctionNodeId $symbol = null, int $depth = 5): Graph
438	    {
439	        $graph = new Graph();
440	
441	        $funcId = $symbol ?? $this->generator->functionNodeId();
442	        $func = new FunctionNode(
443	            id: $funcId,
444	            resolved: $this->generator->boolean(),
445	            meta: $this->generator->fileMeta(),
446	        );
447	        $graph->addNode($func);
448	
449	        if ($depth === 0) {
450	            return $graph;
451	        }
