26	/**
27	 * Command to inspect the dependency tree of a PHP function, method, or class.
28	 *
29	 * The command is the input and output boundary. It declares the command line, stacks
30	 * the configuration sources, runs the inspection and hands the result to the reporter
31	 * the configuration asks for. It decides nothing about analysis or presentation: which
32	 * analyzer runs is the use case's decision, and which reporter renders is the reporter
33	 * factory's, so this class holds no branch on either.
34	 */
35	#[AsCommand(
36	    name: 'inspect',
37	    description: 'Show dependency tree of a PHP function/method/class.',
38	    hidden: false,
39	)]
40	final class InspectCommand extends Command
41	{
42	    /**
43	     * @param InspectAction   $action    The inspection to run
44	     * @param ReporterFactory $reporters Chooses the reporter the configuration asks for
45	     */
46	    public function __construct(
47	        private readonly InspectAction $action,
48	        private readonly ReporterFactory $reporters = new ReporterFactory(),
49	    ) {
50	        parent::__construct();
51	    }
52	
53	    /**
54	     * Declares the arguments and options the command accepts.
55	     */
56	    #[Override]
57	    protected function configure(): void
58	    {
59	        $this->setDefinition(new InputDefinition([
60	            new InputArgument('target', InputArgument::REQUIRED, 'Namespace\ClassName, Namespace\ClassName::methodName or Namespace\functionName'),
61	            new InputArgument('path', InputArgument::OPTIONAL, 'Base directory to analyze (default: current working dir)'),
62	            new InputOption('config', null, InputOption::VALUE_REQUIRED, 'Path to config file (default: <cwd>/.peq.yaml)', getcwd().'/.peq.yaml'),
63	            new InputOption('direction', 'D', InputOption::VALUE_REQUIRED, 'Dependency direction: uses|used-by (default: uses)'),
64	            new InputOption('level', 'L', InputOption::VALUE_REQUIRED, 'Limit depth of the dependency graph'),
65	            new InputOption('reverse', 'R', InputOption::VALUE_NONE, 'Shortcut for --direction used-by'),
66	            new InputOption('include', 'I', InputOption::VALUE_IS_ARRAY | InputOption::VALUE_REQUIRED, 'Include patterns', []),
67	            new InputOption('exclude', 'E', InputOption::VALUE_IS_ARRAY | InputOption::VALUE_REQUIRED, 'Exclude patterns', []),
68	            new InputOption('type', null, InputOption::VALUE_REQUIRED, 'Analyzer type (phpstan|debug)'),
69	            new InputOption('debug-depth', null, InputOption::VALUE_REQUIRED, 'Debug analyzer depth'),
70	            new InputOption('debug-seed', null, InputOption::VALUE_REQUIRED, 'Debug analyzer seed'),
71	            new InputOption('memory-limit', null, InputOption::VALUE_REQUIRED, 'Memory limit (e.g. 1G, 256M)'),
72	        ]));
73	    }
74	
75	    /**
76	     * Runs the inspection and writes its report.
77	     *
78	     * @param InputInterface  $input  The parsed command line
79	     * @param OutputInterface $output Where the report and any error is written
80	     *
81	     * @return int Command::SUCCESS, Command::INVALID for unusable arguments, or
82	     *             Command::FAILURE when the configuration or the symbol is rejected
83	     */
84	    #[Override]
85	    protected function execute(InputInterface $input, OutputInterface $output): int
86	    {
87	        $memoryLimit = $input->getOption('memory-limit');
88	        if (is_string($memoryLimit)) {
89	            ini_set('memory_limit', $memoryLimit);
90	        }
91	
92	        $target = $input->getArgument('target');
93	        if (!is_string($target)) {
94	            $output->writeln('<error>The target must be written as a single symbol name.</error>');
95	
96	            return Command::INVALID;
97	        }
98	
99	        $configPath = $input->getOption('config');
100	        if (!is_string($configPath)) {
101	            $output->writeln('<error>The --config option must be a path to a file.</error>');
102	
103	            return Command::INVALID;
104	        }
105	
106	        try {
107	            $config = (new ConfigLoader([
108	                new DefaultConfigReader(),
109	                new YamlConfigLoader($configPath),
110	                new EnvConfigReader(),
111	                new InputConfigReader($input),
112	            ]))->load();
113	
114	            $result = $this->action->execute(new InspectActionInput(
115	                config: $config,
116	                target: $target,
117	            ));
118	        } catch (ConfigException|SymbolNotFoundException $rejected) {
119	            $output->writeln(sprintf('<error>%s</error>', $rejected->getMessage()));
120	
121	            return Command::FAILURE;
122	        }
123	
124	        $this->reporters->create($config)->report($result->graph, $result->symbol->id(), $output);
125	
126	        return Command::SUCCESS;
127	    }
128	}

