9	/**
10	 * Configuration data as a source reported it, read one field at a time.
11	 *
12	 * A configuration reader knows how its own source spells things — an environment
13	 * variable is always a string, a YAML scalar is already typed, a console option
14	 * may be absent. None of them know what the application needs a field to be. This
15	 * type is where that decision is made, once: every accessor states the type it
16	 * requires, converts a value that can honestly be read as that type, and raises a
17	 * ConfigException naming the field and what was found when it cannot.
18	 *
19	 * Keeping the conversion here rather than in each reader is what lets the readers
20	 * stay pass-through, and what makes "level must be a positive integer" one rule
21	 * rather than one rule per source.
22	 */
23	final class RawConfig
24	{
25	    /**
26	     * @param array<string, mixed> $values The field values a source reported
27	     */
28	    public function __construct(
29	        private readonly array $values,
30	    ) {}
31	
32	    /**
33	     * Reports whether the source mentioned a field at all.
34	     *
35	     * @param string $key The field name
36	     *
37	     * @return bool True when the field is present, even if its value is null
38	     */
39	    public function has(string $key): bool
40	    {
41	        return array_key_exists($key, $this->values);
