import pathlib, re

single = {
    'ClassNodeId': ('className', 'class'),
    'InterfaceNodeId': ('interfaceName', 'interface'),
    'TraitNodeId': ('traitName', 'trait'),
    'EnumNodeId': ('enumName', 'enum'),
    'FunctionNodeId': ('functionName', 'function'),
    'BuiltinNodeId': ('name', 'builtin type'),
}
double = {
    'MethodNodeId': ('methodName', 'className', 'method', 'class'),
    'PropertyNodeId': ('propertyName', 'className', 'property', 'class'),
    'ConstantNodeId': ('constantName', 'className', 'constant', 'class'),
    'EnumCaseNodeId': ('caseName', 'enumName', 'enum case', 'enum'),
}

base = pathlib.Path('src/Analyzer/Graph/NodeId')

for cls, (second, what) in single.items():
    p = base / f'{cls}.php'
    s = p.read_text()
    method = f'''
    /**
     * Builds the identifier from a fully qualified name.
     *
     * @param string $fullName The fully qualified {what} name, as analysis reported it
     *
     * @return self The identifier for that {what}
     */
    public static function of(string $fullName): self
    {{
        $name = new QualifiedName($fullName);

        return new self($name->namespace, $name->shortName);
    }}
'''
    anchor = '\n    /**\n     * Returns the string representation of this identifier.'
    assert anchor in s, cls
    s = s.replace(anchor, method + anchor, 1)
    s = s.replace('use App\\Analyzer\\Graph\\NodeId;', 'use App\\Analyzer\\Graph\\NodeId;\nuse App\\Analyzer\\Graph\\QualifiedName;', 1)
    p.write_text(s)

for cls, (member, ownerParam, memberWhat, ownerWhat) in double.items():
    p = base / f'{cls}.php'
    s = p.read_text()
    method = f'''
    /**
     * Builds the identifier from the fully qualified name of the declaring {ownerWhat}.
     *
     * @param string $ownerName  The fully qualified {ownerWhat} name, as analysis reported it
     * @param string ${member} The name of the {memberWhat}
     *
     * @return self The identifier for that {memberWhat}
     */
    public static function of(string $ownerName, string ${member}): self
    {{
        $owner = new QualifiedName($ownerName);

        return new self($owner->namespace, $owner->shortName, ${member});
    }}
'''
    anchor = '\n    /**\n     * Returns the string representation of this identifier.'
    assert anchor in s, cls
    s = s.replace(anchor, method + anchor, 1)
    s = s.replace('use App\\Analyzer\\Graph\\NodeId;', 'use App\\Analyzer\\Graph\\NodeId;\nuse App\\Analyzer\\Graph\\QualifiedName;', 1)
    p.write_text(s)

print('ok')
