import pathlib, re

PARAM_DESC = {
    'node': 'The syntax node met during analysis',
    'scope': 'The analyser scope it was written in',
    'sourceNode': 'The symbol it is written inside, resolved from the scope when omitted',
    'type': 'The written type, or null when none was written',
    'source': 'The symbol the expression is written inside',
}

base = pathlib.Path('src/Analyzer/PhpStanAnalyzer/Processor')
pattern = re.compile(
    r'    /\*\*\n((?:     \* [^@\n][^\n]*\n|     \*\n)*)     \* (@return [^\n]+)\n     \*/\n    public static function (\w+)\(([^)]*)\)( *: *[^\n{]+)')

for p in sorted(base.glob('*.php')):
    s = p.read_text()

    def repl(m):
        prose, ret, fn, params, rettype = m.group(1), m.group(2), m.group(3), m.group(4), m.group(5)
        entries = []
        for raw in [x.strip() for x in params.split(',') if x.strip()]:
            pm = re.match(r'^([^\s]+)\s+\$(\w+)(?:\s*=.*)?$', raw)
            if not pm:
                return m.group(0)
            ptype, pname = pm.group(1), pm.group(2)
            if ptype.startswith('?'):
                ptype = 'null|' + ptype[1:]
            entries.append((ptype, pname))
        if not entries:
            return m.group(0)
        wt = max(len(t) for t, _ in entries)
        wn = max(len(n) for _, n in entries)
        lines = ['     * @param {} ${} {}'.format(t.ljust(wt), n.ljust(wn), PARAM_DESC.get(n, 'The value to process'))
                 for t, n in entries]
        if prose.strip():
            head = prose.rstrip('\n') + '\n     *\n'
        else:
            head = '     * Records what this declaration or expression brings into the graph.\n     *\n'
        return ('    /**\n' + head + '\n'.join(lines) + '\n     *\n     * ' + ret
                + ' The relations it describes\n     */\n    public static function ' + fn + '(' + params + ')' + rettype)

    s2 = pattern.sub(repl, s)
    if s2 != s:
        p.write_text(s2)
print('done')
