# name -> (member param name or None, sample namespace, sample owner name, sample member, separator)
SPECS = {
    'BuiltinNodeId':   (None, 'App\\\\Domain', 'Money', None, ''),
    'ClassNodeId':     (None, 'App\\\\Domain', 'Invoice', None, ''),
    'EnumNodeId':      (None, 'App\\\\Domain', 'InvoiceState', None, ''),
    'FunctionNodeId':  (None, 'App\\\\Domain', 'formatMoney', None, ''),
    'InterfaceNodeId': (None, 'App\\\\Domain', 'Payable', None, ''),
    'TraitNodeId':     (None, 'App\\\\Domain', 'Timestamped', None, ''),
    'ConstantNodeId':  ('constantName', 'App\\\\Domain', 'Invoice', 'MAX_ITEMS', '::'),
    'EnumCaseNodeId':  ('caseName', 'App\\\\Domain', 'InvoiceState', 'OPEN', '::'),
    'MethodNodeId':    ('methodName', 'App\\\\Domain', 'Invoice', 'total', '::'),
    'PropertyNodeId':  ('propertyName', 'App\\\\Domain', 'Invoice', 'lines', '::'),
}
OWNER_PARAM = {
    'BuiltinNodeId': 'name', 'ClassNodeId': 'className', 'EnumNodeId': 'enumName',
    'FunctionNodeId': 'functionName', 'InterfaceNodeId': 'interfaceName', 'TraitNodeId': 'traitName',
    'ConstantNodeId': 'className', 'EnumCaseNodeId': 'enumName', 'MethodNodeId': 'className',
    'PropertyNodeId': 'className',
}

out = pathlib.Path('tests/Unit/Analyzer/Graph/NodeId')
for cls, (member, ns, owner, memberName, sep) in SPECS.items():
    ns_php = ns.replace('\\\\', '\\')
    full = ns_php + '\\' + owner
    rendered = full + (sep + memberName if member else '')
    ctor_args = "'" + ns_php.replace('\\', "\\\\") + "', '" + owner + "'" + (", '" + memberName + "'" if member else '')
    of_args = "'" + full.replace('\\', "\\\\") + "'" + (", '" + memberName + "'" if member else '')
    rendered_php = rendered.replace('\\', "\\\\")
    subject = 'method' if member else 'name'

    body = f'''<?php

declare(strict_types=1);

namespace Tests\\Unit\\Analyzer\\Graph\\NodeId;

use App\\Analyzer\\Graph\\NodeId\\{cls};
use PHPUnit\\Framework\\Attributes\\CoversClass;
use PHPUnit\\Framework\\Attributes\\Small;
use PHPUnit\\Framework\\TestCase;

/**
 * @internal
 */
#[CoversClass({cls}::class)]
#[Small]
final class {cls}Test extends TestCase
{{
    public function testToStringJoinsTheParts(): void
    {{
        self::assertSame('{rendered_php}', (new {cls}({ctor_args}))->toString());
    }}

    public function testToStringOmitsTheSeparatorWithoutANamespace(): void
    {{
        self::assertSame('{(owner + (sep + memberName if member else "")).replace(chr(92), chr(92)*2)}', (new {cls}('', '{owner}'{", '" + memberName + "'" if member else ''}))->toString());
    }}

    public function testOfSplitsAFullyQualifiedName(): void
    {{
        $id = {cls}::of({of_args});

        self::assertSame('{ns_php.replace(chr(92), chr(92)*2)}', $id->namespace);
        self::assertSame('{owner}', $id->{OWNER_PARAM[cls]});
    }}

    public function testOfBuildsTheSameIdentifierAsTheConstructor(): void
    {{
        self::assertSame(
            (new {cls}({ctor_args}))->toString(),
            {cls}::of({of_args})->toString(),
        );
    }}

    public function testOfLeavesTheNamespaceEmptyForAGlobalName(): void
    {{
        self::assertSame('', {cls}::of('{owner}'{", '" + memberName + "'" if member else ''})->namespace);
    }}
}}
'''
    (out / f'{cls}Test.php').write_text(body)
