13	/**
14	 * The position of one tree report as it is being written.
15	 *
16	 * A traversal hands nodes over one at a time in depth-first order and says nothing
17	 * about layout. Turning that stream into a tree needs memory: which branches are
18	 * still open above the current line, which node was the parent at each depth, which
19	 * identifiers are on the current path, and which ones were already expanded
20	 * somewhere else. That memory belongs to a single report, so it lives here rather
21	 * than in the reporter, and every decision it drives is a named method rather than
22	 * a captured variable.
23	 *
24	 * @visibility namespace
25	 */
26	final class TreeCursor
27	{
28	    /**
29	     * @var array<int, bool> Whether the branch at each depth continues below the current line
30	     */
31	    private array $continuations = [];
32	
33	    /**
34	     * @var array<int, Node> The node that was visited last at each depth
35	     */
36	    private array $parents = [];
37	
38	    /**
39	     * @var list<string> The identifiers on the path from the root to the current line
40	     */
41	    private array $path = [];
42	
43	    /**
44	     * @var array<string, true> The identifiers already expanded somewhere in this report
45	     */
46	    private array $expanded = [];
47	
48	    /**
49	     * @param Graph           $graph        The graph being reported on
50	     * @param Traversal       $traversal    The traversal whose edges decide sibling order
51	     * @param LineRenderer    $lineRenderer The format of a single line
52	     * @param OutputInterface $output       Where lines are written
53	     * @param null|int        $level        Deepest level to print, or null for the whole tree
54	     */
55	    public function __construct(
56	        private readonly Graph $graph,
57	        private readonly Traversal $traversal,
58	        private readonly LineRenderer $lineRenderer,
59	        private readonly OutputInterface $output,
60	        private readonly ?int $level = null,
61	    ) {}
62	
63	    /**
64	     * Writes one node and reports whether the tree should continue below it.
65	     *
66	     * A node is not expanded twice in one report: the second time it appears it is
67	     * marked and left closed, which keeps a shared dependency from multiplying the
68	     * output. A node on the current path is a cycle and is marked as such. Builtin
69	     * and unresolved nodes have nothing below them to print.
70	     *
71	     * @param Node $node  The node the traversal reached
72	     * @param int  $depth How far below the root symbol it sits
73	     *
74	     * @return bool True when the traversal should descend into this node
75	     */
76	    public function visit(Node $node, int $depth): bool
77	    {
78	        if ($this->level !== null && $depth > $this->level) {
79	            return false;
80	        }
81	
82	        while (count($this->path) > $depth) {
83	            array_pop($this->path);
84	        }
85	
86	        $nodeKey = $node->id()->toString();
87	        $isRecursive = in_array($nodeKey, $this->path, true);
88	        $isDuplicate = !$isRecursive && isset($this->expanded[$nodeKey]);
89	        $isLastChild = $this->isLastChild($node, $depth);
90	
91	        $this->output->writeln($this->lineRenderer->render(
92	            node: $node,
93	            depth: $depth,
94	            continuationFlags: $this->continuations,
95	            isLastChild: $isLastChild,
96	            isRecursive: $isRecursive,
97	            isDuplicate: $isDuplicate,
98	        ));
99	
100	        $this->continuations[$depth] = !$isLastChild;
101	        $this->parents[$depth] = $node;
102	        if (!$isRecursive) {
103	            $this->path[] = $nodeKey;
104	        }
105	
106	        if ($isRecursive || $isDuplicate || $this->isLeafKind($node->kind())) {
107	            return false;
108	        }
109	
110	        $this->expanded[$nodeKey] = true;
111	
112	        return true;
113	    }
114	
115	    /**
116	     * Reports whether a node is the last of the children drawn under its parent.
117	     *
118	     * The answer decides between a `└──` and a `├──` prefix, and it is asked of the
119	     * graph rather than of the traversal, because the traversal has already moved on
120	     * by the time the line is written.
121	     *
122	     * @param Node $node  The node being written
123	     * @param int  $depth How far below the root symbol it sits
124	     *
125	     * @return bool True when no further sibling follows it
126	     */
127	    public function isLastChild(Node $node, int $depth): bool
128	    {
129	        $parent = $depth > 0 ? ($this->parents[$depth - 1] ?? null) : null;
130	        if ($parent === null) {
131	            return true;
132	        }
133	
134	        $siblings = [];
135	        foreach ($this->graph->edges($parent->id()) as $edge) {
136	            if ($edge->kind()->direction() === $this->traversal->direction()) {
137	                $siblings[] = $edge->to()->toString();
138	            }
139	        }
140	
141	        $siblings = array_unique($siblings);
142	        if ($siblings === []) {
143	            return true;
144	        }
145	
146	        return $node->id()->toString() === end($siblings);
147	    }
148	
149	    /**
150	     * Reports whether a kind of node can have anything printed below it.
151	     *
152	     * A builtin type and an unresolved reference are both outside the analyzed
153	     * sources, so the graph holds no relations for them to descend into.
154	     *
155	     * @param NodeKind $kind The kind of the node being written
156	     *
157	     * @return bool True when the node is a leaf of the printed tree
158	     */
159	    public function isLeafKind(NodeKind $kind): bool
160	    {
