162	            NodeKind::Builtin,
163	            NodeKind::Unknown => true,
164	
165	            NodeKind::Klass,
166	            NodeKind::Constant,
167	            NodeKind::EnumCase,
168	            NodeKind::Enum,
169	            NodeKind::Function,
170	            NodeKind::Interface,
171	            NodeKind::Method,
172	            NodeKind::Property,
173	            NodeKind::Trait => false,
174	        };
175	    }
