    bad = set(invalid.get(test, []))

    covers, uses = [], []
    for iface in sorted(bad):
        impls = sorted(u for u in units if implements(u, iface))
        if not impls:
            print('NO IMPLEMENTATION EXECUTED for', iface, 'in', test)
        covers.extend(impls)
        units -= set(impls)
        # drop the invalid target
        short = iface.rsplit('\\', 1)[1]
        for form in (f'#[CoversClass({short}::class)]\n', f'#[CoversClass(\\{iface}::class)]\n'):
            if form in s:
                s = s.replace(form, '')
                break
        else:
            print('COVERS LINE NOT FOUND for', iface, 'in', test)
    uses = sorted(units)

