    def valid_target(u):
        info = src_map.get(u)
        return bool(info) and info['kind'] not in ('interface', 'trait')
    covers = [u for u in covers if valid_target(u)]
    uses = [u for u in uses if valid_target(u)]
    dropped = [u for u in sorted(units) if not valid_target(u)]
    if dropped:
        print('SKIPPED non-target units in', test, dropped)

    lines = [f'#[CoversClass(\\{u}::class)]' for u in covers] + [f'#[UsesClass(\\{u}::class)]' for u in uses]
    if not lines:
