    if anchor:
        insert_at = anchor.end()
    else:
        m = re.search(r'^(?:#\[[^\n]*\]\n)*final class ', s, re.M)
        insert_at = m.start()
    s = s[:insert_at] + '\n'.join(lines) + '\n' + s[insert_at:]

