     */
    public function option(string $name): bool|float|int|string|array|null
    {
        $value = $this->input->getOption($name);
        if (!is_array($value)) {
            return $this->reported($name, $value);
        }

        $values = [];
        foreach ($value as $item) {
            $values[] = $this->reported($name, $item);
        }

        return $values;
