public static function buildUnionType(int &$counter, int $maxDepth): UnionType
{
    $count = mt_rand(2, 4);
    $types = [];
    for ($i = 0; $i < $count; ++$i) {
        $types[] = self::buildUnionMember($counter, $maxDepth);
