import pathlib, re

src = pathlib.Path('tests/Contract/Analyzer/TypeResolverContractTest.php').read_text()
start = src.index('    public static function buildTypeTree(int $seed): ?Node')
body = src[start:src.rindex('}\n')]

fixture = '''<?php

declare(strict_types=1);

namespace Tests\\Fixture\\Analyzer;

use PhpParser\\Node;
use PhpParser\\Node\\Identifier;
use PhpParser\\Node\\IntersectionType;
use PhpParser\\Node\\Name;
use PhpParser\\Node\\NullableType;
use PhpParser\\Node\\UnionType;

/**
 * Type expressions drawn at random, and the count of names written in them.
 *
 * A type position can hold a name, a builtin, a nullable, a union of either, or an
 * intersection inside a union, and the resolver has to answer the same question of
 * all of them. Drawing them from a seed covers shapes nobody would think to write
 * down, and counting the names in the drawn tree is what gives the check something
 * to compare the resolver's answer against.
 */
final class GeneratedTypeTrees
{
    /**
     * The names PHP resolves itself, which a drawn tree mixes in with declared ones.
     *
     * @var list<string>
     */
    private const BUILTINS = ['int', 'string', 'float', 'bool', 'null', 'void', 'never', 'mixed', 'array', 'object', 'callable', 'iterable', 'self', 'parent', 'static'];

    /**
     * Names each seed the resolver is checked over.
     *
     * @return iterable<string, array{int}> The seeds, one per case
     */
    public static function seeds(): iterable
    {
        foreach ([1, 3, 17, 42, 128, 777, 1234, 4321, 9999, 31337] as $seed) {
            yield sprintf('seed %d', $seed) => [$seed];
        }
    }

'''
# reuse the builders verbatim, with docblocks
docs = {
 'buildTypeTree': ('Draws the type expression one seed describes.', '@param int $seed The seed to draw with', '@return null|Node The drawn type, which may be no type at all'),
 'buildTypeNode': ('Draws a type expression of any shape, down to a depth.', "@param int \\$counter How many names have been drawn so far\n     * @param int \\$maxDepth How much deeper the expression may nest", '@return null|Node The drawn type'),
 'buildLeafOrNull': ('Draws a type that nests no further.', '@param int $counter How many names have been drawn so far', '@return null|Node The drawn type'),
 'buildLeafNode': ('Draws a builtin or a declared name.', '@param int $counter How many names have been drawn so far', '@return Identifier|Name The drawn type'),
 'buildUnionType': ('Draws a union of two to four members.', "@param int \\$counter  How many names have been drawn so far\n     * @param int \\$maxDepth How much deeper the expression may nest", '@return UnionType The drawn union'),
 'buildUnionMember': ('Draws one member of a union.', "@param int \\$counter  How many names have been drawn so far\n     * @param int \\$maxDepth How much deeper the expression may nest", '@return Identifier|IntersectionType|Name The drawn member'),
 'buildIntersectionType': ('Draws an intersection of two or three names.', '@param int $counter How many names have been drawn so far', '@return IntersectionType The drawn intersection'),
 'makeName': ('Draws a declared name nobody else has been given.', '@param int $counter How many names have been drawn so far', '@return Name The drawn name'),
 'makeNameParts': ('Draws the segments of a fully qualified declared name.', '@param int $counter How many names have been drawn so far', '@return list<string> The segments'),
 'pickBuiltin': ('Picks one of the names PHP resolves itself.', None, '@return string The name'),
 'countNameLeaves': ('Counts the declared names written anywhere in a type expression.', '@param null|Node $type The type expression', '@return int How many names it writes'),
}

# split the copied body into methods and add docblocks
methods = re.split(r'\n(?=    (?:/\*\*|public static function ))', body)
out = []
for m in methods:
    if not m.strip():
        continue
    name_match = re.search(r'public static function (\w+)\(', m)
    if not name_match:
        out.append(m)
        continue
    name = name_match.group(1)
    m = re.sub(r'    /\*\*(?:(?!\*/).)*?\*/\n', '', m, flags=re.S)
    summary, params, ret = docs[name]
    doc = '    /**\n     * ' + summary + '\n     *\n'
    if params:
        doc += '     * ' + params + '\n     *\n'
    doc += '     * ' + ret + '\n     */\n'
    out.append(doc + m.lstrip('\n'))

fixture += '\n'.join(out).rstrip() + '\n}\n'
fixture = fixture.replace('self::', 'self::')
pathlib.Path('tests/Fixture/Analyzer/GeneratedTypeTrees.php').write_text(fixture)
